def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", resp)
    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit", 0) or 0

    if outcome == "declined":
        return {"action": "decline", "limit": 0}

    # self_employed with requested_limit > 6000 must go to manual review
    # (a decline stays a decline, handled above)
    if app.get("employment") == "self_employed" and app.get("requested_limit", 0) > 6000:
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": credit_limit}

    # manual_review / refer / anything undetermined
    return {"action": "queue_review", "limit": 0}
